/*
 * prog17_whitespace_trim.c
 *
 * Behaviour observed in the original binary:
 *   • If no command‑line argument is supplied, prints "EMPTY".
 *   • Takes the first argument (argv[1]) as input.
 *   • Considers the characters space, '\t', '\n', '\r', '\v', '\f' as whitespace
 *     (the same set used by the C library function `isspace`).
 *   • Trims leading and trailing whitespace.
 *   • Collapses any run of one or more whitespace characters inside the
 *     string to a single space character.
 *   • Processes at most the first 400 characters of the input (longer strings
 *     are silently truncated).
 *   • If the resulting string is empty, prints "EMPTY".
 *   • Otherwise prints the trimmed string followed by a newline (via `puts`).
 *
 * The program reproduces exactly the observable behaviour of the original
 * obfuscated binary while being clear and idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 400          /* maximum number of characters to examine */
#define OUT_BUF_SIZE (MAX_INPUT + 1)   /* space for the terminating NUL */

int main(int argc, char *argv[])
{
    /* No argument → "EMPTY" */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *in = argv[1];
    size_t in_len = strlen(in);
    if (in_len > MAX_INPUT) {
        in_len = MAX_INPUT;               /* truncate to 400 characters */
    }

    char out[OUT_BUF_SIZE];
    size_t out_len = 0;

    int have_word = 0;    /* have we output any non‑whitespace character yet? */
    int pending_space = 0;/* a whitespace run has been seen after a word */

    for (size_t i = 0; i < in_len; ++i) {
        unsigned char ch = (unsigned char)in[i];

        if (isspace(ch)) {
            /* Skip leading whitespace */
            if (!have_word) {
                continue;
            }
            /* Remember that we have seen whitespace after a word */
            pending_space = 1;
        } else {
            /* If a whitespace run preceded this character, insert a single space */
            if (pending_space && out_len > 0) {
                out[out_len++] = ' ';
            }
            out[out_len++] = (char)ch;
            have_word = 1;
            pending_space = 0;
        }
    }

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        out[out_len] = '\0';
        puts(out);
    }

    return 0;
}
